// marks.cpp - Input, sum, average, max and min using an array
#include <iostream>
using namespace std;

int main() {
    const int N = 5;
    int marks[N];

    cout << "Enter marks of " << N << " students: ";
    for (int i = 0; i < N; i++)
        cin >> marks[i];

    int sum = 0, maxM = marks[0], minM = marks[0];
    for (int i = 0; i < N; i++) {
        sum += marks[i];
        if (marks[i] > maxM) maxM = marks[i];
        if (marks[i] < minM) minM = marks[i];
    }

    cout << "Marks   : ";
    for (int i = 0; i < N; i++) cout << marks[i] << " ";
    cout << endl;
    cout << "Total   : " << sum << endl;
    cout << "Average : " << (float)sum / N << endl;
    cout << "Highest : " << maxM << endl;
    cout << "Lowest  : " << minM << endl;
    return 0;
}

