// linear.cpp - Linear search
#include <iostream>
using namespace std;

int linearSearch(int arr[], int n, int key) {
    for (int i = 0; i < n; i++)
        if (arr[i] == key)
            return i;           // found: return index
    return -1;                  // not found
}

int main() {
    int roll[] = {12, 45, 7, 23, 56, 89, 34};
    int n = sizeof(roll) / sizeof(roll[0]);
    int key;
    cout << "Enter roll number to search: ";
    cin >> key;

    int pos = linearSearch(roll, n, key);
    if (pos != -1)
        cout << key << " found at index " << pos << endl;
    else
        cout << key << " not found" << endl;
    return 0;
}

// binary.cpp - Binary search on a sorted array
#include <iostream>
using namespace std;

int binarySearch(int arr[], int n, int key) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (arr[mid] == key)
            return mid;
        else if (arr[mid] < key)
            low = mid + 1;      // search right half
        else
            high = mid - 1;     // search left half
    }
    return -1;
}

int main() {
    int a[] = {5, 12, 18, 25, 33, 47, 52, 68, 74, 91};
    int key;
    cout << "Enter number to search: ";
    cin >> key;
    int pos = binarySearch(a, 10, key);
    if (pos != -1) cout << "Found at index " << pos << endl;
    else           cout << "Not found" << endl;
    return 0;
}

// bubble.cpp - Bubble sort
#include <iostream>
using namespace std;

void bubbleSort(int arr[], int n) {
    for (int pass = 0; pass < n - 1; pass++) {
        bool swapped = false;
        for (int j = 0; j < n - 1 - pass; j++) {
            if (arr[j] > arr[j + 1]) {
                int t = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = t;
                swapped = true;
            }
        }
        if (!swapped) break;    // already sorted
    }
}

void display(int arr[], int n) {
    for (int i = 0; i < n; i++) cout << arr[i] << " ";
    cout << endl;
}

int main() {
    int a[] = {64, 25, 12, 22, 11};
    int n = 5;
    cout << "Before: "; display(a, n);
    bubbleSort(a, n);
    cout << "After : "; display(a, n);
    return 0;
}

// frequency.cpp - Count how many times each value appears
#include <iostream>
using namespace std;

int main() {
    int a[] = {2, 5, 2, 8, 5, 2, 9};
    int n = 7;
    bool counted[7] = {false};

    for (int i = 0; i < n; i++) {
        if (counted[i]) continue;
        int count = 1;
        for (int j = i + 1; j < n; j++) {
            if (a[j] == a[i]) {
                count++;
                counted[j] = true;
            }
        }
        cout << a[i] << " appears " << count << " time(s)" << endl;
    }
    return 0;
}

// matrix.cpp - 2-D array: matrix addition and transpose
#include <iostream>
using namespace std;

int main() {
    int A[2][3] = {{1, 2, 3}, {4, 5, 6}};
    int B[2][3] = {{6, 5, 4}, {3, 2, 1}};
    int C[2][3];

    cout << "A + B =" << endl;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 3; j++) {
            C[i][j] = A[i][j] + B[i][j];
            cout << C[i][j] << " ";
        }
        cout << endl;
    }

    cout << "Transpose of A =" << endl;
    for (int j = 0; j < 3; j++) {
        for (int i = 0; i < 2; i++)
            cout << A[i][j] << " ";
        cout << endl;
    }
    return 0;
}

