// evenodd.cpp - Split numbers into even and odd vectors
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> nums, even, odd;
    int n, x;
    cout << "How many numbers? ";
    cin >> n;
    cout << "Enter " << n << " numbers: ";
    for (int i = 0; i < n; i++) {
        cin >> x;
        nums.push_back(x);
    }

    for (int value : nums) {
        if (value % 2 == 0) even.push_back(value);
        else                odd.push_back(value);
    }

    cout << "Even: ";
    for (int e : even) cout << e << " ";
    cout << "\nOdd : ";
    for (int o : odd) cout << o << " ";
    cout << endl;
    return 0;
}

