    int m[3][3];
    cout << "Enter 9 elements row by row:" << endl;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            cin >> m[i][j];

    for (int i = 0; i < 3; i++) {
        int rs = 0;
        for (int j = 0; j < 3; j++) rs += m[i][j];
        cout << "Row " << i << " sum = " << rs << endl;
    }
    for (int j = 0; j < 3; j++) {
        int cs = 0;
        for (int i = 0; i < 3; i++) cs += m[i][j];
        cout << "Column " << j << " sum = " << cs << endl;
    }

    bool symmetric = true;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            if (m[i][j] != m[j][i]) symmetric = false;
    cout << (symmetric ? "Symmetric matrix" : "Not symmetric") << endl;
    return 0;
}
